export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text using uppercase, lowercase, or slug mode.',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'The text to transform.' },
          mode: {
            type: 'string',
            enum: ['uppercase', 'lowercase', 'slug'],
            description: 'The transform mode.'
          },
          trim: { type: 'boolean', default: true, description: 'Trim surrounding whitespace (default true).' }
        },
        required: ['text', 'mode'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }

  validateArgs(args);

  const { text, mode, trim = true } = args;
  const result = transform(text, mode, trim);

  return { content: [{ type: 'text', text: result }] };
}

function validateArgs(args) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = new Set(['text', 'mode', 'trim']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected argument: ${key}`);
    }
  }

  if (!('text' in args)) {
    throw new Error('Missing required argument: text');
  }
  if (typeof args.text !== 'string') {
    throw new Error('Argument "text" must be a string');
  }

  if (!('mode' in args)) {
    throw new Error('Missing required argument: mode');
  }
  if (typeof args.mode !== 'string') {
    throw new Error('Argument "mode" must be a string');
  }
  if (!VALID_MODES.has(args.mode)) {
    throw new Error(`Invalid mode: ${args.mode}. Must be one of uppercase, lowercase, slug.`);
  }

  if ('trim' in args) {
    if (typeof args.trim !== 'boolean') {
      throw new Error('Argument "trim" must be a boolean');
    }
  }
}

function transform(text, mode, trim) {
  let out = text;

  if (mode === 'slug') {
    if (trim) out = out.trim();
    out = out.toLowerCase();
    out = out.replace(/[^a-z0-9]+/g, '-');
    out = out.replace(/^-+|-+$/g, '');
    return out;
  }

  if (mode === 'uppercase') {
    out = out.toUpperCase();
  } else if (mode === 'lowercase') {
    out = out.toLowerCase();
  }

  if (trim) out = out.trim();
  return out;
}

